import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForEl2,validEl2,advanceEl2,numericEl2,experimentOptions,experimentResult,experimentCases,experimentValid}from './el2-models.js?v=20261023-physicscomplete01';import{showEl2}from './el2-visuals.js?v=20261023-physicscomplete01';export{showEl2};
export function mountEl2(l,p,root,{save,done,feedback}){let ts=tasksForEl2(l.widget.slice(4)),w=p.widget;w.el2Task??=ts[0].id;w.el2Drafts??={};w.el2Passed??=[];let i=ts.findIndex(t=>t.id===w.el2Task);if(i<0)i=0;let t=ts[i],v=w.el2Drafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountEl2(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.el2Passed.includes(t.id));
syncProcessMovie(l,1,{process:false});
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('el2Case','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('el2Answer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealEl2">Reveal evidence →</button><p id="el2Readout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showEl2(t.kind,{state:c[0],title:t.title,label:c[1],concealed:!r,progress:r?1:0,step:r?5:0});$('#el2Readout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validEl2(c,v.answer);}
else if(t.type==='sequence'){body=field('el2Next','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceEl2">Advance pathway →</button><p id="el2Readout" aria-live="polite"></p>';draw=()=>{showEl2(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#el2Readout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}

else if(t.type==='experiment'){let o=experimentOptions[t.experiment];v.a??=o.a[0][0];v.b??=o.b[0][0];v.observed??=[];body=field('el2A',o.labels[0],o.a,v.a)+field('el2B',o.labels[1],o.b,v.b)+'<label class="field-label">Predict / '+o.unit+'<input class="lab-input" type="number" step="any" id="el2Prediction" value="'+(v.prediction??'')+'"></label><button class="secondary" id="el2Run">Reveal model output →</button><p id="el2Output"></p>'+field('el2Interpretation','Conclusion',[['limited','A bounded illustrative comparison; evaluate omitted effects'],['universal','This output proves the best decision for every real system']],v.interpretation);draw=()=>{let r=experimentResult(t.experiment,v.a,v.b);showEl2(t.kind,{a:v.a,b:v.b,wiring:v.wiring,revealed:v.ran,title:t.title});$('#el2Output').textContent=v.ran?'Model output: '+Number(r.value.toFixed(3))+' '+o.unit:('R' in r&&['thermistor','ldr'].includes(t.experiment)?'Supplied sensorR: '+Number(r.R.toFixed(3))+' Ω. Predict current in mA.':'Predict first. Use the displayed resistors, sourcepd and branch-current rules.');};valid=()=>!!v.ran&&numericEl2(v.prediction,experimentResult(t.experiment,v.a,v.b).value);}
else{body='<p>'+t.prompt+'</p><label class="field-label" for="el2Number">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="el2Number" type="number" step="any" value="'+(v.number??'')+'">'+field('el2Reason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showEl2(t.kind,{title:t.title,label:'Original illustrative evidence'});valid=()=>numericEl2(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="el2Evidence"></p><div class="lab-actions"><button class="secondary" id="recordEl2">Record reasoning</button><button class="secondary" id="nextEl2">Next challenge →</button></div><p id="el2Progress"></p>';
const status=()=>{$('#el2Evidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):t.type==='experiment'?'Recorded settings: '+v.observed.join('; '):w.el2Passed.includes(t.id)?'Challenge recorded.':'';$('#el2Progress').textContent=ts.filter(t=>w.el2Passed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='el2A'||id==='el2B'){if(!val){remount();return;}v[id==='el2A'?'a':'b']=val;v.ran=false;v.prediction='';save();remount();return;}if(id==='el2Interpretation'){v.interpretation=val;save();return;}if(id==='el2Prediction'){v.prediction=val;save();return;}if(id==='el2Case'){if(val===''){remount();return;}v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='el2Answer')v.answer=val;else if(id==='el2Next')v.next=val;else if(id==='el2Number')v.number=val;else if(id==='el2Reason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{v[e.target.id==='el2Prediction'?'prediction':'number']=e.target.value;save();};}
if($('#el2Run'))$('#el2Run').onclick=()=>{if(v.prediction===''||v.prediction===undefined){feedback('Predict a number first.',true);return;}v.ran=true;save();draw();};
if($('#revealEl2'))$('#revealEl2').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validEl2(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validEl2(t.cases[v.case],v.answer));};
if($('#advanceEl2'))$('#advanceEl2').onclick=()=>{let n=advanceEl2(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordEl2').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);if(t.type==='experiment'){let key=v.a+':'+v.b;if(!v.observed.includes(key))v.observed.push(key);}let finished=t.type==='experiment'?experimentValid(t.experiment,v):t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.el2Passed.includes(t.id))w.el2Passed.push(t.id);p.widgetDone=ts.every(t=>w.el2Passed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':t.type==='experiment'&&experimentCases(t.experiment).every(k=>v.observed.includes(k))?'All required settings recorded. Choose a conclusion that respects the model limits.':'Recorded. Compare the remaining scenarios.');};$('#nextEl2').onclick=()=>{if(!w.el2Passed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.el2Task=ts[(i+1)%ts.length].id;save();remount();};}
